// One-time prod repair: regenerate baked battle-log wording inside
// game_state snapshots (and the per-member realtime rows' logs) with the
// CURRENT engine. Log text is generated by logLine() when an event is
// applied, so lines baked by an older engine keep its old wording forever
// ("attacked X for 1 damage" instead of "dealt the final blow").
//
// SURGICAL by design: the replay is used ONLY as a source of freshly-worded
// log lines. The snapshot's players/day/seq/outcomes are left exactly as
// they happened — an old-engine bug must not resurrect a dead tank. Per
// game: replay canonical history; if replayed seq or the log's seq-per-index
// diverges from the snapshot, the game is SKIPPED and reported instead.
//
// Backups taken before running (2026-11-15):
//   - backups/prod-data-2026-11-15-pre-relog.sql  (full data dump)
//   - backups/prod-schema-2026-11-15-pre-relog.sql
//   - tables relog_backup_game_state_20261115 / relog_backup_player_activity_20261115
//     (RLS enabled, no policies — API-invisible, SQL-editor-restorable)
//
// Run:  SUPABASE_ACCESS_TOKEN=<pat> deno run --allow-net --allow-env scripts/relog-repair.ts
//       (add --apply to actually write; default is a dry run)

import { applyEvent, createInitialState } from '../supabase/functions/_shared/engine_src/index.ts';
import {
  attackActors, attackMask, maskLog, viewerLogReveal,
} from '../supabase/functions/_shared/engine_src/index.ts';
import {
  canonicalHistory, effectiveForks, type ForkPoint,
} from '../supabase/functions/_shared/history.ts';
import type { GameConfig, GameEvent, GameState, LogEntry, PlayerSpec } from '../supabase/functions/_shared/engine_src/types.ts';

const REF = 'sifbpmpxyiycbupntobl';
const PAT = Deno.env.get('SUPABASE_ACCESS_TOKEN');
const APPLY = Deno.args.includes('--apply');
if (!PAT) {
  console.error('SUPABASE_ACCESS_TOKEN env var required');
  Deno.exit(1);
}

async function query(sql: string): Promise<unknown> {
  const res = await fetch(`https://api.supabase.com/v1/projects/${REF}/database/query`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${PAT}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: sql }),
  });
  const body = await res.json();
  if (!res.ok) throw new Error(`query failed (${res.status}): ${JSON.stringify(body)}`);
  return body;
}

const q = (s: string) => s.replace(/'/g, "''");

interface GameRow { id: string; name: string; mode: string; config: GameConfig; cur_generation: number; fork_seq: number | null }
interface SnapRow { game_id: string; seq: number; state: GameState }
interface EventRow { game_id: string; generation: number; seq: number; type: GameEvent['type']; actor_id: string; payload: unknown; created_at: string }
interface ForkRow extends ForkPoint { game_id: string }
interface MemberRow { game_id: string; player_id: string; seq: number; state: GameState & { log?: unknown[] } }

const [games, snaps, events, forks, members] = await Promise.all([
  query('select id, name, mode, config, cur_generation, fork_seq from public.games') as Promise<GameRow[]>,
  query('select game_id, seq, state from public.game_state') as Promise<SnapRow[]>,
  query('select game_id, generation, seq, type, actor_id, payload, created_at from public.events order by game_id, seq') as Promise<EventRow[]>,
  query('select game_id, parent_generation, to_seq from public.game_forks') as Promise<ForkRow[]>,
  // player_activity = the per-member realtime state rows (0016); game_players is membership
  query('select game_id, player_id, seq, state from public.player_activity') as Promise<MemberRow[]>,
]);

console.log(`games=${games.length} snapshots=${snaps.length} events=${events.length} memberRows=${members.length}`);

let applied = 0, unchanged = 0, skipped = 0;
const samples: string[] = [];
const skippedGames: Array<{ game: string; reason: string }> = [];

for (const snap of snaps) {
  const g = games.find((x) => x.id === snap.game_id);
  const st = snap.state;
  if (!g || !st || !Array.isArray(st.log)) {
    skipped++; skippedGames.push({ game: snap.game_id, reason: 'missing game row or log array' });
    continue;
  }
  const rows = events.filter((e) => e.game_id === g.id).map((e) => ({
    seq: e.seq, type: e.type, actorId: e.actor_id, createdAt: e.created_at,
    payload: (e.payload ?? {}) as GameEvent['payload'], generation: e.generation,
  }));
  const history = canonicalHistory(rows, effectiveForks(
    forks.filter((f) => f.game_id === g.id), g.cur_generation, g.fork_seq,
  ));

  // replay with the current engine — log-line SOURCE only
  const specs: PlayerSpec[] = st.order.map((id) => ({
    id, name: st.players[id]?.name ?? id,
    isBot: st.players[id]?.isBot ?? false,
    botDifficulty: st.players[id]?.botDifficulty ?? null,
  }));
  let replayed: GameState;
  try {
    replayed = createInitialState(g.config, specs);
    for (const e of history) replayed = applyEvent(replayed, e);
  } catch (err) {
    skipped++; skippedGames.push({ game: g.id, reason: `replay threw: ${err instanceof Error ? err.message : String(err)}` });
    continue;
  }
  if (replayed.seq !== st.seq) {
    skipped++; skippedGames.push({ game: g.id, reason: `seq mismatch replay=${replayed.seq} snapshot=${st.seq}` });
    continue;
  }
  if (replayed.log.length !== st.log.length) {
    skipped++; skippedGames.push({ game: g.id, reason: `log length mismatch replay=${replayed.log.length} snapshot=${st.log.length}` });
    continue;
  }

  // patch text/kind per index — only where wording diverges
  let changed = 0;
  let patch: Array<{ i: number; before: string; after: string }>;
  let newLog: LogEntry[];
  try {
    patch = [];
    newLog = st.log.map((line: LogEntry, i: number) => {
      const r = replayed.log[i];
      if (r.seq !== line.seq) throw new Error(`seq-per-index divergence at log[${i}] (${line.seq} vs ${r.seq})`);
      if (r.text === line.text && r.kind === line.kind) return line;
      changed++;
      patch.push({ i, before: line.text, after: r.text });
      return { ...r };
    });
  } catch (err) {
    skipped++; skippedGames.push({ game: g.id, reason: err instanceof Error ? err.message : String(err) });
    continue;
  }

  // lifetime AP: the replay accumulates apEarned from day 1 (exact — drips,
  // jury bonuses, starting grant), while legacy snapshots only carry the
  // ??=ap baseline (or nothing), which loses spent AP. The replay was proven
  // equal to the snapshot above, so its counters are the truth.
  const earnedPatch: Array<{ name: string; from: number | null; to: number }> = [];
  const patchedPlayers = { ...st.players };
  for (const id of Object.keys(patchedPlayers)) {
    const r = replayed.players[id];
    const cur = patchedPlayers[id].apEarned;
    if (r && r.apEarned != null && cur !== r.apEarned) {
      earnedPatch.push({ name: patchedPlayers[id].name, from: cur ?? null, to: r.apEarned });
      patchedPlayers[id] = { ...patchedPlayers[id], apEarned: r.apEarned };
    }
  }

  if (changed === 0 && earnedPatch.length === 0) { unchanged++; continue; }

  samples.push(`[${g.name}] ${changed}/${st.log.length} lines` +
    (earnedPatch.length ? `, apEarned: ${earnedPatch.map((p) => `${p.name} ${p.from ?? 'none'}->${p.to}`).join(', ')}` : '') +
    (patch.length ? ': ' + patch.slice(0, 2).map((p) => `"${p.before}" -> "${p.after}"`).join(' | ') : ''));

  // per-member realtime rows: same patched log, masked per viewer (the mask
  // is recomputed from canonical history — deterministic, same as tick)
  const mask = attackMask(history as unknown as GameEvent[]);
  const actors = attackActors(history as unknown as GameEvent[]);
  const namer = (id: string) => st.players[id]?.name ?? id;
  const patchedState = { ...st, log: newLog, players: patchedPlayers };
  const memberUpdates: string[] = [];
  for (const m of members.filter((x) => x.game_id === g.id && x.state && Array.isArray(x.state.log))) {
    const reveal = viewerLogReveal(patchedState, m.player_id);
    const log = reveal
      ? newLog
      : maskLog(newLog, actors, m.player_id, mask, namer);
    // member rows carry the owner's real apEarned (others are scrubbed to -1)
    const rowPlayers = { ...m.state.players };
    const mine = rowPlayers[m.player_id];
    const rMine = replayed.players[m.player_id];
    if (mine && rMine?.apEarned != null && mine.apEarned !== rMine.apEarned) {
      rowPlayers[m.player_id] = { ...mine, apEarned: rMine.apEarned };
    }
    memberUpdates.push(
      `update public.player_activity set state = '${q(JSON.stringify({ ...m.state, log, players: rowPlayers }))}'::jsonb ` +
      `where game_id = '${g.id}' and player_id = '${m.player_id}';`,
    );
  }

  if (APPLY) {
    await query(`update public.game_state set state = '${q(JSON.stringify(patchedState))}'::jsonb where game_id = '${g.id}';`);
    for (const u of memberUpdates) await query(u);
  }
  applied++;
}

console.log(`\nAPPLY=${APPLY} — would update: ${applied}, unchanged: ${unchanged}, skipped: ${skipped}`);
for (const s of samples) console.log('  ' + s);
for (const s of skippedGames) console.log(`  SKIP ${s.game}: ${s.reason}`);
